entries[167832] = { ["name"] = "Canned Minnows", ["text"] = "Binds when picked up\nUse: Restores ( 13200 / 5 * 20) health and ( 8000 / 5 * 20) mana over 20 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and increase your movement speed by 46 for 1 hour while in Mechagon.\nSell Price:" }
entries[167833] = { ["name"] = "Fathom Dredgers", ["text"] = "Binds when picked up\nHands Cloth\n3 Armor\n+5 Intellect\n+7 Stamina\n+ 5 Haste\n+ 2 Versatility\nDurability 55 / 55\nEquip: Every 10000 mana spent grants you a shield absorbing [ 15 * (1 + Versatility)] damage for 8 sec, up to a maximum absorb of [ 147 * (1 + Versatility)].\nSell Price:" }
entries[167834] = { ["name"] = "Stormglide Steps", ["text"] = "Binds when picked up\nFeet Leather\n6 Armor\n+5 [Agility or Intellect]\n+7 Stamina\n+ 5 Versatility\nDurability 80 / 80\nEquip: Your auto attacks grant Untouchable for 15 sec, stacking up to 10 times. Untouchable grants 1 Critical Strike. Taking any damage removes all stacks of Untouchable.\nSell Price:" }
entries[167835] = { ["name"] = "Malformed Herald's Legwraps", ["text"] = "Binds when picked up\nLegs Cloth\n5 Armor\n+6 Intellect\n+9 Stamina\n+ 8 Critical Strike\nDurability 120 / 120\nUse: Open a fissure to the void beneath you for 12 sec, increasing your Haste by 26 . Moving out of the fissure will cause it to collapse, dealing 532 Shadow damage to you. (1 Min Cooldown)\nSell Price:" }
