entries[168022] = { ["name"] = "Plans: Khaz'gorian Smithing Hammer", ["text"] = "Binds when picked up\nUse: Teaches you how to craft a Khaz'gorian Smithing Hammer.\nCreate a Khaz'gorian Hammer.\nRequires Kul Tiran Blacksmithing (150)\nSell Price:\nKhaz'gorian Smithing Hammer\nBinds when picked up\nUnique\nBlacksmithing Tool When crafting blacksmithing armor or weapons, there's a chance it will be given the \"Indestructible\" property.\nUse: Allows the user to repair a piece of their equipment instantly. (1 Hour Cooldown)\nEquip: +4 Blacksmithing Skill.\nRequires Kul Tiran Blacksmithing (150)\n\"This hammer may be used in lieu of a normal blacksmithing hammer for crafting.\"\nRequires Titan's Blood (30), Precision Blessing Tools , Azerokk's Fist , Storm Silver Ore (30), Platinum Ore (20), Expulsom (10)" }
entries[168024] = { ["name"] = "Formula: Iwen's Enchanting Rod", ["text"] = "Binds when picked up\nUse: Teaches you how to craft Iwen's Enchanting Rod.\nCreate Iwen's Enchanting Rod.\nRequires Kul Tiran Enchanting (150)\nSell Price:\nIwen's Enchanting Rod\nBinds when picked up\nUnique\nGain extra resources when disenchanting.\nUse: Consume 1 Veiled Crystal to animate an inert golem. (5 Sec Cooldown)\nRequires Kul Tiran Enchanting (150)\n\"Drust magic causes the rod to thrum with power. Can also serve as any lesser runed enchanting rod.\"\nRequires Grasping Wicker Arm , Runestone of Thros , Lingering Drust Essence (50), Umbra Shard (20), Veiled Crystal (10), Expulsom (10)" }
entries[168025] = { ["name"] = "Book of Schematics: Ub3r-Spanner", ["text"] = "Binds when picked up\nUse: Re-learn any engineering schematics that you learned via questing for your Tool of the Trade, but forgot after switching professions.\nRequires Kul Tiran Engineering (150)\nSell Price:" }
entries[168026] = { ["name"] = "Book of Techniques: Sanguine Feather Quill of Lana'thel", ["text"] = "Binds when picked up\nUse: Re-learn any inscription recipes that you learned via questing for your Tool of the Trade, but forgot after switching professions.\nRequires Kul Tiran Inscription (150)\nSell Price:" }
entries[168027] = { ["name"] = "Design: Jewelhammer's Focus", ["text"] = "Binds when picked up\nUse: Teaches you how to craft Jewelhammer's Focus.\nCut a focusing lens.\nRequires Kul Tiran Jewelcrafting (150)\nSell Price:\nJewelhammer's Focus\nBinds when picked up\nUnique\nAllows the holder to interact with shrines around Kul Tiras and Zandalar, focusing the light from the zone through the lens in order to create a geode of gems.\nUse: Using the focus, carefully extract an embedded gem from one of your socketed items.\nRequires Kul Tiran Jewelcrafting (150)\nRequires Sweete's Diamond-Studded Spyglass , Unrefined Azerite Geode , Fine Azerite Powder (50), Kraken's Eye (5), Expulsom (10)" }
entries[168028] = { ["name"] = "Pattern: Mallet of Thunderous Skins", ["text"] = "Binds when picked up\nUse: Teaches you how to craft a Mallet of Thunderous Skins.\nCreate a Mallet of Thunderous Skins.\nRequires Kul Tiran Leatherworking (150)\nSell Price:\nMallet of Thunderous Skins\nBinds when picked up\nUnique\nAllows you to interact with Drums of Primal Might, granting you a blessing of speed, might, or resilience.\nUse: Increases your Haste by 15%. Lasts 40 sec.\n\nYou will become Exhausted and be unable to benefit from Bloodlust, Heroism or Time Warp again for 10 min. (10 Min Cooldown)\nRequires Kul Tiran Leatherworking (150)\n\"Useful for shaping pieces of leather and as a percussive instrument.\"\nRequires Long Regal Sinew (4), Spirit of the Bested (15), Blood-Stained Bone (50), Tempest Hide (50), Hardened Tempest Hide (25), Expulsom (10)" }
entries[168029] = { ["name"] = "Pattern: Synchronous Thread", ["text"] = "Binds when picked up\nUse: Teaches you how to craft a Synchronous Thread.\nCreate Synchronous Thread.\nRequires Kul Tiran Tailoring (150)\nSell Price:\nSynchronous Thread\nBinds when picked up\nUnique\nKul Tiran and Zandalari cloth displaced in time can be found more often in the world.\nUse: Allows Synchronous Tailors to mend tears in the fabric of time across Kul Tiras and Zandalar.\nRequires Kul Tiran Tailoring (150)\n\"A stitch in time saves the world from its demise.\"\nRequires Essence of the Troll Dynasty , Essence of the Regal Loa , Essence of the Depths , Essence of the Sands , Tidespray Linen (75), Nylon Thread (75), Expulsom (10)" }
